import{_ as u,C as c,o as r,c as h,a9 as t,b as i,w as a,a as n,E as o,a8 as l,j as g}from"./chunks/framework.BOiBTRPC.js";const D=JSON.parse('{"title":"Databricks vs Snowflake","description":"The two lakehouse heavyweights dissected — architecture, pricing meters, isolation, governance, and when the right answer is neither.","frontmatter":{"title":"Databricks vs Snowflake","description":"The two lakehouse heavyweights dissected — architecture, pricing meters, isolation, governance, and when the right answer is neither."},"headers":[],"relativePath":"cloud/lakehouse-platforms.md","filePath":"cloud/lakehouse-platforms.md"}'),m={name:"cloud/lakehouse-platforms.md"},p={class:"details custom-block"};function b(f,e,y,k,w,v){const s=c("Mermaid"),d=c("QuizCard");return r(),h("div",null,[e[6]||(e[6]=t('<h1 id="databricks-vs-snowflake" tabindex="-1">Databricks vs Snowflake <a class="header-anchor" href="#databricks-vs-snowflake" aria-label="Permalink to &quot;Databricks vs Snowflake&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — This is <em>the</em> platform decision of the decade for most data orgs, and it&#39;s genuinely not obvious: they converged on the same &quot;lakehouse&quot; idea from opposite directions. Snowflake built a warehouse that learned to do data science; Databricks built a data science platform that learned SQL. Knowing where each came from tells you where each is still weak.</p></blockquote><h2 id="how-each-is-actually-built" tabindex="-1">How each is actually built <a class="header-anchor" href="#how-each-is-actually-built" aria-label="Permalink to &quot;How each is actually built&quot;">​</a></h2><h3 id="databricks-your-storage-their-compute" tabindex="-1">Databricks: your storage, their compute <a class="header-anchor" href="#databricks-your-storage-their-compute" aria-label="Permalink to &quot;Databricks: your storage, their compute&quot;">​</a></h3><p>Databricks is <strong>control plane + compute</strong>. Your data lives in <strong>your cloud object storage</strong> (S3/ADLS/GCS) as Delta or Iceberg tables. Databricks runs clusters — all-purpose, jobs, or SQL warehouses — inside your cloud account (or its own, for serverless), and bills you <strong>DBUs</strong> on top of the underlying VM cost.</p>',5)),(r(),i(l,null,{default:a(()=>[o(s,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20YourCloud%5B%22Your%20cloud%20account%22%5D%0A%20%20%20%20%20%20%20%20subgraph%20DBX%5B%22Databricks%20workspaces%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20AP%5B%22All-purpose%20clusters%3Cbr%2F%3Enotebooks%2C%20jobs%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20JW%5B%22SQL%20warehouses%3Cbr%2F%3EPhoton%20%2B%20DBSQL%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20SV%5B%22Serverless%20compute%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20OS%5B%22Your%20object%20store%3Cbr%2F%3ES3%20%2F%20ADLS%20%2F%20GCS%3Cbr%2F%3EDelta%20or%20Iceberg%20tables%22%5D%0A%20%20%20%20%20%20%20%20AP%20--%3E%20OS%0A%20%20%20%20%20%20%20%20JW%20--%3E%20OS%0A%20%20%20%20%20%20%20%20SV%20--%3E%20OS%0A%20%20%20%20end%0A%20%20%20%20CP%5B%22Databricks%20control%20plane%3Cbr%2F%3Eworkspace%20UI%2C%20jobs%2C%20UC%22%5D%0A%20%20%20%20CP%20--%3E%20DBX%0A%20%20%20%20UC%5B%22Unity%20Catalog%22%5D%20-.governs.-%3E%20OS%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p>Key consequence: <strong>you keep the data if you leave</strong>. The tables are open-format files in your bucket — Trino, Athena, Snowflake (via Iceberg) can read them in place. This is the strongest lock-in counter-argument Databricks has.</p><h3 id="snowflake-their-storage-their-compute" tabindex="-1">Snowflake: their storage, their compute <a class="header-anchor" href="#snowflake-their-storage-their-compute" aria-label="Permalink to &quot;Snowflake: their storage, their compute&quot;">​</a></h3><p>Snowflake is a <strong>managed service running on a cloud you pick per region</strong>. Data loads into Snowflake&#39;s own centralized storage (compressed, micro-partitioned columnar — you never see the files). Compute is <strong>virtual warehouses</strong>: independent T-shirt-sized clusters (XS→6XL) billed in <strong>credits per second</strong> with auto-suspend.</p>',3)),(r(),i(l,null,{default:a(()=>[o(s,{id:"mermaid-27",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20SF%5B%22Snowflake%20account%20%E2%80%94%20one%20region%2Fcloud%22%5D%0A%20%20%20%20%20%20%20%20subgraph%20VW%5B%22Virtual%20warehouses%20%E2%80%94%20independent%20compute%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20WH1%5B%22WH-XS%3Cbr%2F%3EETL%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20WH2%5B%22WH-L%3Cbr%2F%3EBI%20dashboards%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20WH3%5B%22WH-M%3Cbr%2F%3Edata%20science%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20ST%5B%22Snowflake%20managed%20storage%3Cbr%2F%3Emicro-partitions%2C%20FDN%20or%20Iceberg%22%5D%0A%20%20%20%20%20%20%20%20WH1%20--%3E%20ST%0A%20%20%20%20%20%20%20%20WH2%20--%3E%20ST%0A%20%20%20%20%20%20%20%20WH3%20--%3E%20ST%0A%20%20%20%20%20%20%20%20SVC%5B%22Services%20layer%3Cbr%2F%3Eauth%2C%20optimizer%2C%20metadata%2C%20cache%22%5D%0A%20%20%20%20%20%20%20%20WH1%20--%3E%20SVC%0A%20%20%20%20%20%20%20%20WH2%20--%3E%20SVC%0A%20%20%20%20%20%20%20%20WH3%20--%3E%20SVC%0A%20%20%20%20end%0A%20%20%20%20EXT%5B%22Iceberg%20tables%20on%20YOUR%20storage%3Cbr%2F%3Evia%20Open%20Catalog%20%2F%20external%20volumes%22%5D%20-.-%3E%20SVC%0A%20%20%20%20HZ%5B%22Horizon%20Catalog%22%5D%20-.governs.-%3E%20ST%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=t('<p>Key consequence: <strong>compute isolation is trivial</strong>. Every warehouse is a separate cluster on shared storage — a runaway BI query can&#39;t touch the ETL warehouse&#39;s CPU. But the <em>default</em> data path puts bytes inside Snowflake&#39;s storage format, which is the lock-in — mitigated by Iceberg tables on external storage.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ One sentence each</p><ul><li><strong>Databricks</strong> = &quot;run any engine on your open files; we sell compute and a workspace.&quot;</li><li><strong>Snowflake</strong> = &quot;hand us the data; we sell a finished product with compute you can dial up and down.&quot;</li></ul></div><h2 id="side-by-side" tabindex="-1">Side-by-side <a class="header-anchor" href="#side-by-side" aria-label="Permalink to &quot;Side-by-side&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Databricks</th><th>Snowflake</th></tr></thead><tbody><tr><td>Storage</td><td><strong>Your object store</strong>, Delta/Iceberg open formats</td><td><strong>Their managed storage</strong> (proprietary micro-partitions); Iceberg-on-your-bucket now first-class</td></tr><tr><td>Compute unit</td><td><strong>DBU/hr + cloud VM cost</strong> per cluster</td><td><strong>Credits/sec</strong> per virtual warehouse (XS=1 credit/hr, doubles each size)</td></tr><tr><td>Idle behavior</td><td>Clusters auto-<strong>terminate</strong> after N min (config)</td><td>Warehouses auto-<strong>suspend</strong> after N min (default 10, set to 1–2 for BI)</td></tr><tr><td>Engine</td><td><strong>Photon</strong> (C++ Spark engine) for SQL; open-source Spark underneath</td><td>Proprietary engine; Snowpark for Python/Java/Scala push-down</td></tr><tr><td>SQL polish</td><td>DBSQL good, improving fast</td><td>Best-in-class: near-zero tuning, excellent concurrency</td></tr><tr><td>ML/AI</td><td>Best-in-class: native Spark + MLflow + Mosaic AI</td><td>Snowpark ML, Cortex functions; workable, not the strength</td></tr><tr><td>Streaming</td><td>Structured Streaming mature; Delta Live Tables</td><td>Snowpipe streaming, Dynamic Tables; younger, simpler model</td></tr><tr><td>Concurrency model</td><td>More warehouses/clusters = more DBU spend, explicit</td><td>Auto-scale multi-cluster warehouses (up to 10 clusters/WH on Enterprise+)</td></tr><tr><td>Governance</td><td><strong>Unity Catalog</strong> — tables, files, functions, models, volumes; Iceberg REST API</td><td><strong>Horizon Catalog</strong> — same scope; Polaris OSS catalog for Iceberg interop</td></tr><tr><td>Format escape</td><td>Native: Delta/UniForm/Iceberg on your bucket</td><td>Iceberg tables on external storage; FDN data needs unload or Iceberg</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The pricing meters differ in a subtle way interviews love: <strong>DBUs are per-cluster-second and you manage cluster lifetime; credits are per-warehouse-second and suspend is automatic</strong>. A forgotten Databricks all-purpose cluster with a 60-min auto-terminate burns money the same way a forgotten Snowflake warehouse does — but Snowflake&#39;s 60-second auto-suspend default makes the accident cheaper. Both have killed budgets; only one does it by default while you sleep.</p></div><h2 id="delta-vs-iceberg-support-—-where-it-actually-stands" tabindex="-1">Delta vs Iceberg support — where it actually stands <a class="header-anchor" href="#delta-vs-iceberg-support-—-where-it-actually-stands" aria-label="Permalink to &quot;Delta vs Iceberg support — where it actually stands&quot;">​</a></h2><ul><li><strong>Databricks</strong>: Delta is native (Databricks created it). <strong>UniForm</strong> generates Iceberg metadata alongside Delta so external engines read the same files as Iceberg. Unity Catalog exposes an <strong>Iceberg REST catalog</strong> — Snowflake, Trino, and others can read UC-managed tables. Managed Iceberg writes landed in 2025-era releases.</li><li><strong>Snowflake</strong>: Iceberg tables are first-class — either Snowflake-managed catalog or an external catalog (AWS Glue, Polaris/Open Catalog, UC via REST). Delta reads work through UniForm metadata. FDN (Snowflake&#39;s native format) still gives the best engine-internal performance.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Production failure mode: the catalog is the lock-in now</p><p>Everyone fixates on file formats, but 2025-era lock-in moved up a layer: <strong>the catalog</strong>. Delta on your bucket is portable bytes; Unity Catalog&#39;s <em>governance graph</em> (lineage, permissions, volumes, functions) is not. Same for Horizon. Budget for catalog migration, not just table conversion, in any exit plan.</p></div><h2 id="performance-features-that-actually-matter" tabindex="-1">Performance features that actually matter <a class="header-anchor" href="#performance-features-that-actually-matter" aria-label="Permalink to &quot;Performance features that actually matter&quot;">​</a></h2><p>Ignore benchmark wars; these are the features that change real workloads:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Databricks</th><th>Snowflake</th></tr></thead><tbody><tr><td>Query engine acceleration</td><td><strong>Photon</strong> — C++ vectorized engine replacing JVM Spark for SQL/DataFrame ops</td><td>Proprietary vectorized engine — every warehouse is already &quot;Photon-class&quot;</td></tr><tr><td>Data skipping</td><td>Delta stats + <strong>liquid clustering</strong> (successor to Z-ORDER) / OPTIMIZE</td><td><strong>Micro-partition</strong> metadata pruning + <strong>clustering keys</strong> + <strong>search optimization</strong> (point-lookup service)</td></tr><tr><td>Caching</td><td>Disk cache (Delta cache) on cluster SSD; result cache in DBSQL</td><td>Result cache 24h + local SSD cache per warehouse + metadata cache</td></tr><tr><td>Auto-tuning</td><td><strong>Predictive optimization</strong> (auto OPTIMIZE/VACUUM), AQE from Spark</td><td>Automatic: no indexes, no distribution keys to manage at all</td></tr><tr><td>Point lookups</td><td>Photon + liquid clustering</td><td><strong>Search Optimization Service</strong> — purpose-built for needle-in-haystack selects</td></tr></tbody></table>',11)),g("details",p,[e[3]||(e[3]=t('<summary>The tuning-tax asymmetry</summary><p>Snowflake&#39;s architectural bet: <em>remove the knobs</em>. No indexes, no partition keys, no distribution styles — micro-partition pruning + statistics do the work for ~90% of workloads; you only reach for clustering keys or search optimization at extremes. Databricks gives you the knobs — partitioning, liquid clustering, OPTIMIZE schedules, file sizing — and rewards operators who use them. The same asymmetry repeats everywhere: Snowflake optimizes for &quot;nobody has to think about this,&quot; Databricks for &quot;you can think about everything.&quot; Neither is free: Snowflake&#39;s answer when the bet misses is a bigger warehouse.</p><h2 id="delta-lake-mechanics-that-actually-matter-on-databricks" tabindex="-1">Delta Lake mechanics that actually matter on Databricks <a class="header-anchor" href="#delta-lake-mechanics-that-actually-matter-on-databricks" aria-label="Permalink to &quot;Delta Lake mechanics that actually matter on Databricks&quot;">​</a></h2><h3 id="acid-via-delta-log-—-the-commit-protocol" tabindex="-1">ACID via <code>_delta_log</code> — the commit protocol <a class="header-anchor" href="#acid-via-delta-log-—-the-commit-protocol" aria-label="Permalink to &quot;ACID via `_delta_log` — the commit protocol&quot;">​</a></h3><p>Every Delta write is a two-phase affair: the job stages new Parquet files, then commits a single JSON file (<code>0000NN.json</code>) into <code>_delta_log/</code> recording <code>add</code>/<code>remove</code> actions. Readers snapshot-resolve from the latest checkpoint plus commits, so they only ever see whole versions — never half-written files. Concurrent writers fight over the <em>version number</em>, not the files: optimistic concurrency checks what changed since your read and retries or fails.</p>',5)),(r(),i(l,null,{default:a(()=>[o(s,{id:"mermaid-291",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20W%20as%20%22Writer%20job%22%0A%20%20%20%20participant%20S%20as%20%22Parquet%20data%20files%22%0A%20%20%20%20participant%20L%20as%20%22_delta_log%22%0A%20%20%20%20participant%20R%20as%20%22Concurrent%20readers%22%0A%20%20%20%20W-%3E%3ES%3A%20%22write%20new%20data%20files%2C%20invisible%20to%20readers%22%0A%20%20%20%20W-%3E%3EL%3A%20%22attempt%20commit%20N.json%20with%20add%20and%20remove%20actions%22%0A%20%20%20%20alt%20%22version%20N%20already%20committed%22%0A%20%20%20%20%20%20%20%20L--%3E%3EW%3A%20%22conflict%2C%20check%20isolation%20and%20retry%20or%20abort%22%0A%20%20%20%20else%20%22commit%20wins%22%0A%20%20%20%20%20%20%20%20L--%3E%3EW%3A%20%22table%20is%20now%20at%20version%20N%22%0A%20%20%20%20end%0A%20%20%20%20R-%3E%3EL%3A%20%22checkpoint%20plus%20newer%20commits%20give%20snapshot%22%0A%20%20%20%20Note%20over%20R%3A%20%22readers%20see%20only%20committed%20versions%2C%20never%20partial%20writes%22%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p>Periodic checkpoints compact the JSON chain into Parquet so log replay stays cheap; <code>spark.databricks.delta.checkpointPolicies=multiPart</code> splits large checkpoints for very wide tables.</p><h3 id="optimize-z-order-vs-liquid-clustering" tabindex="-1">OPTIMIZE + Z-ORDER vs Liquid Clustering <a class="header-anchor" href="#optimize-z-order-vs-liquid-clustering" aria-label="Permalink to &quot;OPTIMIZE + Z-ORDER vs Liquid Clustering&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th><code>OPTIMIZE ... ZORDER BY</code></th><th>Liquid clustering (<code>CLUSTER BY</code>)</th></tr></thead><tbody><tr><td>Era</td><td>Legacy workhorse, OSS Delta too</td><td>Databricks Runtime 13.3+, default direction for 2024+ tables</td></tr><tr><td>Layout</td><td>Rewrites files with a space-filling-curve sort on 2–4 columns</td><td>Incremental; only unclustered files are rewritten on each run</td></tr><tr><td>Key change</td><td>Static — new filter patterns mean re-running full OPTIMIZE</td><td><code>ALTER TABLE ... CLUSTER BY</code> changes keys without full rewrite</td></tr><tr><td>Skew / high-cardinality</td><td>Degrades when column values are unevenly distributed</td><td>Handles skew better; no partition skew problem at all</td></tr><tr><td>Partitioning</td><td>Sits on top of existing partitions</td><td><strong>Do not partition</strong> clustered tables — clustering replaces partitioning</td></tr><tr><td>Best fit</td><td>Existing partitioned tables you can&#39;t re-create; OSS deployments</td><td>New tables; high-cardinality filter columns; evolving query patterns</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Z-ORDER is static: it optimizes for the data distribution <em>at write time</em> and decays as new data lands — the cookbook&#39;s own warning. Liquid clustering exists precisely because re-Z-ORDERing a drifting table is a treadmill. New table on DBR 15+? <code>CLUSTER BY (filter_col, join_col)</code> and let predictive optimization do the rest. Still on an old partitioned table? Keep OPTIMIZE on a schedule and don&#39;t bother re-clustering monthly — the gain rarely covers the rewrite cost.</p></div>',4))]),e[9]||(e[9]=t('<h3 id="vacuum-and-time-travel-—-the-ops-matrix" tabindex="-1">VACUUM and time travel — the ops matrix <a class="header-anchor" href="#vacuum-and-time-travel-—-the-ops-matrix" aria-label="Permalink to &quot;VACUUM and time travel — the ops matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>What it does</th><th>Gotcha</th></tr></thead><tbody><tr><td><code>VERSION AS OF n</code> / <code>versionAsOf</code></td><td>Read an old snapshot</td><td>Fails if log history was checkpointed/retained past <code>logRetentionDuration</code></td></tr><tr><td><code>TIMESTAMP AS OF</code></td><td>Same, by wall clock</td><td>Maps to newest version ≤ timestamp</td></tr><tr><td><code>RESTORE TABLE t TO VERSION AS OF n</code></td><td>Rollback — itself recorded as a new commit</td><td>Only works while the old data files still exist</td></tr><tr><td><code>VACUUM [RETAIN n HOURS]</code></td><td>Deletes <em>unreferenced</em> data files</td><td>Default floor 7 days (168h); going under it needs a safety opt-out and kills time travel below that window</td></tr><tr><td><code>DESCRIBE HISTORY t</code></td><td>Audit every commit</td><td>Your free lineage at the table level</td></tr></tbody></table><p>Retention knobs: <code>delta.logRetentionDuration</code> (default <strong>30 days</strong>, log history) and <code>delta.deletedFileRetentionDuration</code> (default <strong>7 days</strong>, VACUUM eligibility). Want 60-day time travel? Extend <strong>both</strong> — extending only the log buys you a snapshot you can&#39;t fully resolve, and extending only file retention inflates storage.</p><div class="warning custom-block"><p class="custom-block-title">⚠️</p><p><code>VACUUM</code> never deletes <code>_delta_log</code> files — checkpoints do that. And running <code>OPTIMIZE</code> twice is a no-op: it only rewrites files that don&#39;t meet the target size. Neither op changes <em>what</em> readers see, only how fast they see it.</p></div><h3 id="schema-evolution-—-the-flag-map" tabindex="-1">Schema evolution — the flag map <a class="header-anchor" href="#schema-evolution-—-the-flag-map" aria-label="Permalink to &quot;Schema evolution — the flag map&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag / mode</th><th>Where</th><th>Effect</th></tr></thead><tbody><tr><td><code>option(&quot;mergeSchema&quot;,&quot;true&quot;)</code></td><td>Batch write</td><td>Adds new columns from the incoming DataFrame</td></tr><tr><td><code>spark.databricks.delta.schema.autoMerge.enabled</code></td><td>Session / MERGE</td><td>Evolves target schema during <code>MERGE INTO</code></td></tr><tr><td><code>option(&quot;overwriteSchema&quot;,&quot;true&quot;)</code></td><td>Overwrite write</td><td>Replaces schema wholesale — pairs with <code>mode(&quot;overwrite&quot;)</code></td></tr><tr><td><code>cloudFiles.schemaEvolutionMode</code></td><td>Auto Loader</td><td><code>addNewColumns</code> (default-ish), <code>failOnNewColumns</code>, <code>rescue</code>, <code>none</code> — pick <code>rescue</code> when you&#39;d rather quarantine than break</td></tr><tr><td><code>cloudFiles.schemaHints</code></td><td>Auto Loader</td><td>Overrides inference for specific columns; <code>cloudFiles.inferColumnTypes=true</code> infers real types instead of all-strings</td></tr><tr><td><code>_rescued_data</code> column</td><td>Auto Loader output</td><td>Rows that don&#39;t parse land here instead of dying — the built-in dead-letter</td></tr><tr><td>Column mapping</td><td>Table property</td><td>Enables <code>RENAME COLUMN</code> / <code>DROP COLUMN</code> on existing data</td></tr></tbody></table><h2 id="ingestion-routing-auto-loader-vs-structured-streaming-vs-batch" tabindex="-1">Ingestion routing: Auto Loader vs Structured Streaming vs batch <a class="header-anchor" href="#ingestion-routing-auto-loader-vs-structured-streaming-vs-batch" aria-label="Permalink to &quot;Ingestion routing: Auto Loader vs Structured Streaming vs batch&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source shape</th><th>Pick</th><th>Why</th></tr></thead><tbody><tr><td>Files landing in cloud object storage</td><td><strong>Auto Loader</strong> (<code>cloud_files()</code> in DLT SQL, <code>readStream.format(&quot;cloudFiles&quot;)</code> elsewhere)</td><td>Incremental directory listing or event-notification mode, schema evolution modes, <code>_rescued_data</code></td></tr><tr><td>Kafka / Kinesis / Event Hubs</td><td><strong>Structured Streaming</strong> <code>readStream</code> directly</td><td>Native source connector; manage <code>checkpointLocation</code> yourself</td></tr><tr><td>Delta upstream with <code>enableChangeDataFeed</code></td><td>CDF read (<code>table_changes</code> or stream)</td><td>Bronze→silver change propagation without full scans</td></tr><tr><td>Daily snapshots / small static files</td><td><strong>Plain batch read + MERGE</strong></td><td>Streaming machinery is pure cost here</td></tr></tbody></table><p>The <code>checkpointLocation</code> rule worth tattooing: never hand-delete files <em>inside</em> a checkpoint dir; stop the query and remove the whole directory, or the stream state corrupts.</p><h2 id="the-medallion-recipe-as-actually-run-on-databricks" tabindex="-1">The medallion recipe as actually run on Databricks <a class="header-anchor" href="#the-medallion-recipe-as-actually-run-on-databricks" aria-label="Permalink to &quot;The medallion recipe as actually run on Databricks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Write pattern</th><th>Concrete knobs</th></tr></thead><tbody><tr><td><strong>Bronze</strong></td><td>Append-only <code>STREAMING TABLE</code> from <code>cloud_files</code></td><td><code>cloudFiles.inferColumnTypes</code>, keep <code>_rescued_data</code>; optionally <code>delta.enableChangeDataFeed = true</code> for downstream CDC; no dropping constraints — raw stays raw</td></tr><tr><td><strong>Silver</strong></td><td><code>STREAM(live.bronze)</code> incremental or batch <code>MERGE INTO</code> for upserts</td><td><code>EXPECT</code>/<code>CONSTRAINT ... ON VIOLATION DROP ROW</code> for quality gates; <code>dropDuplicates</code> on the business key before merge; <code>CLUSTER BY</code> the join/filter keys</td></tr><tr><td><strong>Gold</strong></td><td><code>LIVE TABLE</code> (materialized view) aggregating silver</td><td><code>GROUP BY</code> rollups; predictive optimization + liquid clustering on serving columns</td></tr></tbody></table><details class="details custom-block"><summary>DLT semantics behind the pattern</summary><p>Delta Live Tables gives you two persistent abstractions: <strong>streaming tables</strong> process each record exactly once incrementally (bronze, silver); <strong>materialized views</strong> (<code>LIVE TABLE</code>) recompute to always reflect current state (gold). <code>CREATE OR REFRESH</code> means DLT owns dependency tracking and schema inference — you ship the SELECT, it ships the DAG.</p></details><p>:::</p><h2 id="data-sharing-—-snowflake-s-quiet-moat" tabindex="-1">Data sharing — Snowflake&#39;s quiet moat <a class="header-anchor" href="#data-sharing-—-snowflake-s-quiet-moat" aria-label="Permalink to &quot;Data sharing — Snowflake&#39;s quiet moat&quot;">​</a></h2><p><strong>Snowflake data sharing</strong> (Secure Data Sharing / Marketplace) lets providers share live tables across accounts with zero copy — the consumer queries the provider&#39;s micro-partitions directly. Cross-cloud replication handles the multi-cloud case. This is a genuine architectural moat: entire data-marketplace businesses run on it.</p><p>Databricks answers with <strong>Delta Sharing</strong> — an open protocol (OSS server) that shares Delta/Iceberg tables over REST to any recipient, no Databricks account required. More open, more assembly.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Sharing ≠ governance transfer</p><p>Both models share <em>data</em>, not <em>policies</em>. A consumer&#39;s masking policy on their side doesn&#39;t constrain what you granted; your row filters are enforced at share time. Auditing &quot;who read shared data&quot; crosses account boundaries on Snowflake — check your regulator&#39;s stance before enabling outbound shares.</p></div><h2 id="serverless-both-vendors-different-meanings" tabindex="-1">Serverless: both vendors, different meanings <a class="header-anchor" href="#serverless-both-vendors-different-meanings" aria-label="Permalink to &quot;Serverless: both vendors, different meanings&quot;">​</a></h2><ul><li><strong>Databricks serverless</strong>: compute runs in <em>Databricks&#39;</em> cloud account — instant-on, no VPC management, premium DBU rate. Serverless SQL warehouses, serverless jobs, and serverless notebooks each exist. You trade VM-level control and the ability to use your cloud commits/discounts.</li><li><strong>Snowflake serverless</strong>: always was. Warehouses are serverless by definition — you never saw the VM. What you pay extra for instead: <strong>Snowpark-optimized warehouses</strong> (bigger nodes for Python), and services like search optimization billed per-use.</li></ul><p>The trap in both: serverless convenience prices ~1.3–2× equivalent classic compute. For steady-state ETL, classic provisioned clusters (DBX) or right-sized warehouses (SF) are cheaper. For spiky/dev/BI workloads, serverless wins on total cost including idle waste.</p><p>Two Databricks-specific wrinkles on top of that: <strong>Photon</strong> (the C++ vectorized engine) is what makes DBSQL competitive on SQL/BI — turning it off or landing on a runtime without it is a silent 2–4× slowdown on the same DBU spend; and serverless SQL warehouses scale to zero so aggressively that the first query of the day takes a cold-start hit. Predictive optimization (managed tables) runs OPTIMIZE/VACUUM for you — convenient, but it&#39;s its own compute line item you&#39;ll find in <code>system.billing.usage</code>, not free housekeeping.</p><h2 id="cost-model-anatomy" tabindex="-1">Cost model anatomy <a class="header-anchor" href="#cost-model-anatomy" aria-label="Permalink to &quot;Cost model anatomy&quot;">​</a></h2><p>Two bills to decompose, not one price to compare:</p><ul><li><strong>Databricks</strong> = <code>DBU-rate × cluster-hours</code> (vendor) <code>+ VM-cost</code> (cloud provider). Classic compute lets you burn cloud commitments/reserved instances on the VM half — often 30–40% off the total at scale. Serverless = DBUs only, no VM lever.</li><li><strong>Snowflake</strong> = <code>credits × rate</code> per warehouse-second + storage ($/TB-mo, compressed) + services (serverless features bill their own credit meters). Edition (Standard→Business Critical) multiplies the credit rate.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>When finance asks &quot;what does a query cost,&quot; Databricks answers in cluster-seconds amortized across its tenants&#39; jobs; Snowflake answers in warehouse-seconds even when the query used 1% of it. Both are approximations — Snowflake&#39;s is the more honest one since a warehouse&#39;s second is genuinely exclusive to your account during billing. Per-query cost on BigQuery is the only <em>exact</em> per-query answer in the industry.</p></div><h2 id="migration-checklist-reality" tabindex="-1">Migration checklist reality <a class="header-anchor" href="#migration-checklist-reality" aria-label="Permalink to &quot;Migration checklist reality&quot;">​</a></h2><p>Moving between them is a quarter, not a sprint. The workstream order that reflects actual risk:</p><ol><li><strong>Table format &amp; storage</strong> — Iceberg-on-your-bucket makes this mechanical; FDN or UC-managed Delta adds a conversion leg.</li><li><strong>SQL dialect port</strong> — ~70% transpiles automatically (Snowflake↔Spark SQL tools exist); UDFs, semi-structured functions, and stored procedures are the hand-work.</li><li><strong>Permissions &amp; catalog</strong> — rebuild grants/row policies/masking in the new governance layer; no automated path.</li><li><strong>Orchestration &amp; downstream</strong> — task graphs, BI semantic layers, reverse-ETL. Always bigger than estimated.</li><li><strong>Cost re-baseline</strong> — the metering models differ enough that month-1 bills surprise in both directions.</li></ol><details class="details custom-block"><summary>Concurrency numbers worth remembering</summary><ul><li>Snowflake default warehouse runs ~8 concurrent queries before queuing; max concurrency scales with warehouse size. Multi-cluster caps at 10 clusters/warehouse on Enterprise.</li><li>Databricks SQL warehouse: concurrency scales by cluster size (t-shirt) up to its max; serverless warehouses autoscale to demand within a configured range.</li><li>Both degrade the same way under sustained queue pressure: latency climbs before throughput dies. Watch queue depth (<code>QUERY_HISTORY</code> queueing fields on SF; <code>system.query</code> / metrics on DBX), not just p95.</li></ul></details><h2 id="governance-deep-dive-uc-vs-horizon" tabindex="-1">Governance deep dive: UC vs Horizon <a class="header-anchor" href="#governance-deep-dive-uc-vs-horizon" aria-label="Permalink to &quot;Governance deep dive: UC vs Horizon&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Unity Catalog</th><th>Horizon Catalog</th></tr></thead><tbody><tr><td>Object scope</td><td>Tables, volumes (files), functions, models, notebooks, external locations</td><td>Tables, views, stages, policies, tags, semantic models</td></tr><tr><td>Fine-grained</td><td>Row filters + column masks + dynamic views</td><td>Row access policies + masking policies + object tagging</td></tr><tr><td>Lineage</td><td>Built-in, table+column level across UC</td><td>Built-in via Horizon; OpenLineage integration</td></tr><tr><td>Interop</td><td>Iceberg REST catalog endpoint — external engines authenticate to UC</td><td>Polaris (Open Catalog) — OSS Iceberg REST catalog; Apache project</td></tr><tr><td>Federation</td><td><strong>Lakehouse Federation</strong> — query external DBs in place</td><td>External tables, database links; Polaris catalogs external Iceberg</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 The Polaris move</p><p>Snowflake donated its Iceberg REST catalog to Apache as <strong>Polaris</strong> — any engine that speaks Iceberg REST can sit on Polaris-cataloged tables, and Horizon governs them. It&#39;s the clearest signal that the industry settled on Iceberg REST as the catalog protocol. Databricks responded by making UC speak the same protocol. Practical result: a Trino cluster can read both vendors&#39; tables through one catalog interface — the first real &quot;multi-engine, multi-vendor&quot; story that isn&#39;t vaporware.</p></div><details class="details custom-block"><summary>UC system tables — governance you can query</summary><p>Unity Catalog ships <code>system.*</code> schemas an account admin enables once via the UC REST API, then grants like normal tables: <code>system.access.audit</code> (who touched what), <code>system.access.table_lineage</code> (programmatic source→target lineage, joinable to <code>entity_id</code> for run-level attribution), <code>system.billing.usage</code> + <code>system.billing.list_prices</code> (per-SKU DBU cost rollups). Root-cause and impact analysis stop being screenshot hunts: <code>SELECT source_table_full_name, target_table_full_name FROM system.access.table_lineage WHERE target_table_full_name = &#39;cat.schema.table&#39;</code>.</p></details><h2 id="workload-isolation-concurrency" tabindex="-1">Workload isolation &amp; concurrency <a class="header-anchor" href="#workload-isolation-concurrency" aria-label="Permalink to &quot;Workload isolation &amp; concurrency&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Databricks</th><th>Snowflake</th></tr></thead><tbody><tr><td>Isolate ETL from BI</td><td>Separate job clusters vs SQL warehouses — natural, explicit sizing</td><td>Separate virtual warehouses — natural, trivially explicit</td></tr><tr><td>Burst concurrency on BI</td><td>SQL warehouse cluster scaling (classic) or serverless</td><td><strong>Multi-cluster warehouse</strong>: same WH spins up 1→N clusters automatically</td></tr><tr><td>Cost attribution</td><td>Cluster tags → DBU usage tables</td><td>Warehouse names → <code>WAREHOUSE_METERING_HISTORY</code>; resource monitors + budgets</td></tr><tr><td>Kill a noisy query</td><td><code>statement_timeout</code> / cancel via API</td><td>Per-query/per-WH timeout, <code>QUERY_HISTORY</code> audit</td></tr></tbody></table><p>Snowflake&#39;s multi-cluster auto-scaling is genuinely differentiated for spiky BI concurrency: one logical warehouse, compute scales out and back with query queue depth. Databricks answers with serverless SQL warehouses, which scale similarly but bill at a premium serverless DBU rate.</p><h2 id="decision-table" tabindex="-1">Decision table <a class="header-anchor" href="#decision-table" aria-label="Permalink to &quot;Decision table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your situation</th><th>Lean toward</th></tr></thead><tbody><tr><td>ML/DS-heavy, custom Spark, streaming-first, platform team exists</td><td><strong>Databricks</strong></td></tr><tr><td>SQL/BI-heavy, analysts &gt; engineers, want zero-ops</td><td><strong>Snowflake</strong></td></tr><tr><td>Multi-cloud or cloud-exit clause in contracts</td><td><strong>Databricks</strong> (open files on your storage) — or Iceberg-on-Snowflake</td></tr><tr><td>Power BI / Microsoft shop</td><td>Fabric; then Databricks (Azure Databricks is first-party)</td></tr><tr><td>Regulated, single source of truth governance</td><td>Either — UC vs Horizon is a coin flip; pilot the one your cloud favors</td></tr><tr><td>Small team, mostly ad-hoc analytics</td><td><strong>Snowflake</strong> — the ops tax of Databricks isn&#39;t worth it</td></tr><tr><td>Heavy streaming (CDC, near-real-time at scale)</td><td><strong>Databricks</strong> — Structured Streaming is a decade deep</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ The &quot;do both&quot; anti-pattern</p><p>Orgs frequently buy both &quot;for different teams&quot; and end up with two copies of the silver layer, two catalogs, and no answer to &quot;which number is right.&quot; If you run both, draw the line on <em>workload</em> (DBX = transform/ML, SF = serving/BI) and replicate one direction only — never federate writes.</p></div><h2 id="when-the-answer-is-neither" tabindex="-1">When the answer is neither <a class="header-anchor" href="#when-the-answer-is-neither" aria-label="Permalink to &quot;When the answer is neither&quot;">​</a></h2><p>Both are the expensive end of the market. The escape hatch that senior engineers should keep loaded:</p><p><strong>Iceberg on your bucket + a query engine you pay for only when it runs:</strong></p><ul><li><strong>Trino/Starburst</strong> — self-host or managed; the classic open lakehouse query layer</li><li><strong>Athena</strong> — serverless per-TB-scanned on AWS, zero ops, great for ad-hoc</li><li><strong>DuckDB / Polars</strong> — honestly covers analytics up to ~1 TB per query on one box</li><li><strong>ClickHouse / MotherDuck</strong> — when the workload is really &quot;fast dashboards,&quot; not &quot;lakehouse&quot;</li></ul><table tabindex="0"><thead><tr><th>Scenario</th><th>Stack</th><th>Rough monthly shape</th></tr></thead><tbody><tr><td>Team of 3, 10 TB, ad-hoc queries</td><td>Iceberg + Athena/DuckDB</td><td>Storage + $5/TB scanned — often <strong>&lt;$500/mo</strong></td></tr><tr><td>50 TB, dbt + BI, growing team</td><td>Snowflake or Databricks</td><td><strong>$5k–30k/mo</strong> depending on discipline</td></tr><tr><td>500 TB, mixed ML+BI, platform team</td><td>Databricks + Iceberg</td><td><strong>$30k+</strong> but compute-efficient at scale</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The strongest negotiating position in every Snowflake/Databricks renewal is a working proof that your tables are Iceberg and readable by an external engine. It costs a weekend to demonstrate and saves 15–30% at renewal. Vendors price against your switching cost, not your usage.</p></div><h2 id="the-open-format-exit-strategy" tabindex="-1">The open-format exit strategy <a class="header-anchor" href="#the-open-format-exit-strategy" aria-label="Permalink to &quot;The open-format exit strategy&quot;">​</a></h2><p>Whichever you pick, keep the escape hatch warm. A defensible open-format posture:</p>',47)),(r(),i(l,null,{default:a(()=>[o(s,{id:"mermaid-1127",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20RAW%5B%22Your%20object%20store%3Cbr%2F%3EIceberg%20or%20Delta%2BUniForm%3Cbr%2F%3Etables%20you%20own%22%5D%20--%3E%20E1%5B%22Primary%20engine%3Cbr%2F%3EDBX%20or%20SF%22%5D%0A%20%20%20%20RAW%20--%3E%20E2%5B%22Escape%20engine%3Cbr%2F%3ETrino%20%2F%20Athena%20%2F%20DuckDB%22%5D%0A%20%20%20%20CAT%5B%22Catalog%3Cbr%2F%3EUC%20or%20Polaris%3Cbr%2F%3EIceberg%20REST%22%5D%20--%3E%20E1%0A%20%20%20%20CAT%20--%3E%20E2%0A"})]),fallback:a(()=>[...e[5]||(e[5]=[n(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=t('<p>Checklist that keeps it real rather than aspirational:</p><ol><li>Tables in Iceberg (or Delta+UniForm) on <strong>your</strong> bucket with <strong>your</strong> encryption keys.</li><li>An Iceberg REST catalog a third engine can authenticate to — UC or Polaris both qualify.</li><li>One quarterly drill: point Athena/Trino at a real table, run a real query. If nobody&#39;s tested the exit, it&#39;s a slide, not a strategy.</li><li>Keep transforms in dbt where possible — SQL ports across engines; proprietary procedural code doesn&#39;t.</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ What portability doesn&#39;t cover</p><p>Even a perfect open-format posture doesn&#39;t port: Snowpark/MLflow code, stored procedures, tasks/Dynamic Tables vs Databricks Workflows, semantic models, and the governance layer. Realistic switching cost is months, not weeks — the format just removes the <em>data</em> leg, which used to be the killer.</p></div><h2 id="ops-burden-—-what-you-re-actually-signing-up-for" tabindex="-1">Ops burden — what you&#39;re actually signing up for <a class="header-anchor" href="#ops-burden-—-what-you-re-actually-signing-up-for" aria-label="Permalink to &quot;Ops burden — what you&#39;re actually signing up for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ops surface</th><th>Databricks classic</th><th>Databricks serverless</th><th>Snowflake</th></tr></thead><tbody><tr><td>Cluster lifecycle</td><td>You size, schedule, tune pools</td><td>Platform-owned</td><td>Warehouse = one knob</td></tr><tr><td>Version upgrades</td><td>You schedule (LTS channels exist)</td><td>Automatic</td><td>Automatic, forced</td></tr><tr><td>VPC/networking</td><td>You manage (customer VPC)</td><td>Vendor-managed (less control)</td><td>Vendor-managed + PrivateLink</td></tr><tr><td>Capacity planning</td><td>Cluster policies, pools, spot mix</td><td>Min/max on serverless config</td><td>Warehouse size + multi-cluster count</td></tr><tr><td>Paging risk</td><td>Cluster failures, spot kills, init scripts</td><td>Low</td><td>Lowest of the three</td></tr></tbody></table><p>Rough headcount translation: a healthy Databricks classic deployment wants ~0.5–1 FTE of platform attention per few dozen pipelines; Snowflake wants a fraction of that — which is exactly what the credit premium is buying. Price the headcount, not the sticker.</p><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',7)),o(d,{questions:[{q:"A Snowflake warehouse is set to 6XL but suspends after 60s idle. A Databricks all-purpose cluster has 2h auto-terminate. Which idle accident is worse and why?",options:["Databricks — cluster bills DBU+VM for the full idle window; Snowflake bills only while resumed","Snowflake — 6XL is huge","Equal — both bill idle","Neither — both auto-stop instantly"],correct:0,explain:"Snowflake suspends in seconds and bills per-second of uptime; an idle 6XL costs ~nothing once suspended. Databricks auto-terminate is measured in minutes and bills the whole window at DBU + underlying VM rates. Same bug, very different bill."},{q:"What does Delta UniForm do?",options:["A Snowflake storage format","Generates Iceberg metadata alongside a Delta table so external engines read the same files as Iceberg","A Unity Catalog tier","Converts Delta files to Iceberg files"],correct:1,explain:"UniForm writes Iceberg-compatible metadata next to the Delta log — one copy of the Parquet data files, two table-format views. It removes the copy-data tax for cross-engine reads but reads, not writes, are the interoperable side."},{q:"Why is the data catalog now a bigger lock-in risk than the file format?",options:["Catalogs cost more","Formats are portable bytes; the catalog holds lineage, permissions, volumes, functions — governance does not export","Iceberg requires a catalog","Catalogs are proprietary formats"],correct:1,explain:"Iceberg/Delta files move freely. Unity Catalog and Horizon encode the governance graph — who can see what, lineage, semantic models — and none of that ports. Exit plans must budget catalog rebuild, not just table migration."},{q:"Your workload is 40 analysts, dbt models, Power BI dashboards, minimal Python, team of 4 engineers. Default pick?",options:["Databricks — more features","Redshift provisioned","Self-host Trino","Snowflake — SQL/BI-first, near-zero ops, auto-suspend; or Fabric if deep Microsoft shop"],correct:3,explain:"BI-serving at small-team scale is the Snowflake home court: managed everything, multi-cluster concurrency for dashboard bursts, per-second billing. Databricks pays off when Spark/ML workload justifies the ops surface."},{q:"How does Snowflake multi-cluster warehouse scaling differ from adding a second Databricks SQL warehouse?",options:["Databricks cannot scale","Multi-cluster is faster queries","Multi-cluster scales ONE logical warehouse out/in automatically by queue depth; a second DBX warehouse is a separately sized cluster you manage","No difference"],correct:2,explain:"Snowflake spins up additional clusters behind the same warehouse name when queries queue, then spins them down — concurrency without a second endpoint to route to. Databricks classic warehouses scale by cluster count you configure; serverless narrows the gap at a price premium."},{q:"Strongest negotiation lever at a Snowflake or Databricks renewal?",options:["Moving to a different region","Threatening to leave","A demonstrated working read of your tables via Iceberg from an external engine — switching cost, not sentiment, sets the discount","Asking for credits"],correct:2,explain:"Vendors price against switching cost. Iceberg-on-your-bucket readable by Trino/Athena lowers that cost credibly; an account executive prices retention against a real exit path, not a slide deck."}]}),o(d,{questions:[{q:"A Delta table needs 60 days of time travel and a monthly VACUUM. Which properties change?",options:["Neither — checkpoints preserve everything","Both — log retention covers metadata, file retention covers data; extending one alone is useless","Only delta.deletedFileRetentionDuration","Only delta.logRetentionDuration"],correct:1,explain:"delta.logRetentionDuration (default 30d) keeps commit history; delta.deletedFileRetentionDuration (default 7d) gates VACUUM eligibility for data files. Time travel needs both: the log to know which files existed, the files to still exist."},{q:"Liquid clustering vs OPTIMIZE ZORDER BY — the biggest practical difference?",options:["Z-ORDER is newer","Liquid clustering requires partitioning","Liquid clustering is incremental — new data gets clustered on each run without rewriting everything, and keys can change via ALTER","No difference, just syntax"],correct:2,explain:"Z-ORDER rewrites files to match the distribution at optimize time and decays as data drifts; it also assumes partitions. Liquid clustering is incremental, re-keyable via ALTER TABLE CLUSTER BY, and replaces partitioning entirely — never partition a clustered table."},{q:"Where is ACID actually enforced in Delta Lake?",options:["Unity Catalog","Row locks on Parquet files","The _delta_log JSON commit sequence — staged files become visible only when a commit file lands","A lock service in the cloud provider"],correct:2,explain:"Writes stage invisible Parquet files, then one JSON commit records add/remove actions. Readers snapshot-resolve the log and only see committed versions; concurrent writers conflict on the version number, resolved by optimistic concurrency — never on the data files."}]}),e[11]||(e[11]=t('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.databricks.com/en/getting-started/overview.html" target="_blank" rel="noreferrer">Databricks architecture overview</a> — control plane vs compute plane, serverless vs classic</li><li><a href="https://docs.snowflake.com/en/user-guide/intro-key-concepts" target="_blank" rel="noreferrer">Snowflake key concepts and architecture</a> — the three-layer model, warehouses, credits</li><li><a href="https://docs.delta.io/latest/delta-uniform.html" target="_blank" rel="noreferrer">Delta Lake UniForm</a> — Iceberg-compatible reads on Delta</li><li><a href="https://docs.snowflake.com/en/user-guide/tables-iceberg" target="_blank" rel="noreferrer">Snowflake Iceberg tables</a> — external-catalog and Snowflake-managed modes</li><li><a href="https://docs.databricks.com/en/data-governance/unity-catalog/index.html" target="_blank" rel="noreferrer">Unity Catalog</a> and <a href="https://docs.snowflake.com/en/user-guide/security-horizon-intro" target="_blank" rel="noreferrer">Snowflake Horizon Catalog</a> — the governance layer on each side</li><li><a href="https://polaris.apache.org/" target="_blank" rel="noreferrer">Apache Polaris (incubating)</a> — the OSS Iceberg REST catalog Snowflake donated; the interop substrate</li><li><em>Databricks vs Snowflake</em> benchmark posts from both vendors — read both; each picks the workload that wins</li><li><strong>Data Engineering with Databricks Cookbook</strong> — Pulkit Chadha (2024), <a href="https://www.packtpub.com/en-us/product/data-engineering-with-databricks-cookbook-9781837633358" target="_blank" rel="noreferrer">Packt</a> — recipe-style coverage of Delta mechanics, Auto Loader, DLT medallion pipelines, and Unity Catalog ops</li></ul>',2))])}const T=u(m,[["render",b]]);export{D as __pageData,T as default};
